{"file_text": "<div class="message-area">
    <div class="area-header">
        <h2># @Channel.Name</h2>
        <p>@Channel.Description</p>
    </div>

    <div class="message-list">
        @if (HasMoreMessages)
        {
            <div class="load-more-container">
                <button class="load-more-btn" @onclick="OnLoadMore">⬆ Load older messages</button>
            </div>
        }
        @if (Messages.Count == 0)
        {
            <div class="empty-state">
                <p>No messages yet. Start the conversation!</p>
            </div>
        }
        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ThreadSummary="GetThreadSummary(message.Id)"
                         OnReply="() => OnOpenThread.InvokeAsync(message.Id)"
                         OnReact="(emoji) => OnReact.InvokeAsync(new ReactionEventArgs(message.Id, emoji))" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel.Name}")" OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<ReactionEventArgs> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ThreadSummary? GetThreadSummary(int messageId)
        => ThreadSummaries.GetValueOrDefault(messageId);

    public record ReactionEventArgs(int MessageId, string Emoji);
}
", "path": "/tmp/sv-f450356804864cd198bb723d541061d3/Components/Chat/MessageArea.razor"}

